    },
    group = {
        col = {
            border_active = "rgb({{colors.primary|bare}})",
            border_inactive = "rgb({{colors.surface2|bare}})",
        },
    },
    misc = {
        background_color = "rgb({{colors.bg|bare}})",
    },
})
